  assign w_we_dsig_lock = w_wr_en & (reg_addr == LPARA_DSIG_LOCK_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_op = w_wr_en & (reg_addr == LPARA_DSIG_OP_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_set = w_wr_en & (reg_addr == LPARA_DSIG_SET_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_len_msg = w_wr_en & (reg_addr == LPARA_DSIG_LEN_MSG_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_len_ctx = w_wr_en & (reg_addr == LPARA_DSIG_LEN_CTX_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_off_msg = w_wr_en & (reg_addr == LPARA_DSIG_OFF_MSG_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_off_sig = w_wr_en & (reg_addr == LPARA_DSIG_OFF_SIG_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_off_pk = w_wr_en & (reg_addr == LPARA_DSIG_OFF_PK_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_off_res = w_wr_en & (reg_addr == LPARA_DSIG_OFF_RES_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_cmd = w_wr_en & (reg_addr == LPARA_DSIG_CMD_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_err = w_wr_en & (reg_addr == LPARA_DSIG_ERR_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_irq_raw = w_wr_en & (reg_addr == LPARA_DSIG_IRQ_RAW_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_irq_en = w_wr_en & (reg_addr == LPARA_DSIG_IRQ_EN_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_irq_inj = w_wr_en & (reg_addr == LPARA_DSIG_IRQ_INJ_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_alarm = w_wr_en & (reg_addr == LPARA_DSIG_ALARM_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_win_addr = w_wr_en & (reg_addr == LPARA_DSIG_WIN_ADDR_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_win_wr = w_wr_en & (reg_addr == LPARA_DSIG_WIN_WR_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_log_lock = w_wr_en & (reg_addr == LPARA_DSIG_LOG_LOCK_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_rng = w_wr_en & (reg_addr == LPARA_DSIG_RNG_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_tmo = w_wr_en & (reg_addr == LPARA_DSIG_TMO_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_key_0 = w_wr_en & (reg_addr == LPARA_DSIG_KEY_0_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_key_1 = w_wr_en & (reg_addr == LPARA_DSIG_KEY_1_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_key_2 = w_wr_en & (reg_addr == LPARA_DSIG_KEY_2_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_key_3 = w_wr_en & (reg_addr == LPARA_DSIG_KEY_3_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_key_4 = w_wr_en & (reg_addr == LPARA_DSIG_KEY_4_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_key_5 = w_wr_en & (reg_addr == LPARA_DSIG_KEY_5_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_key_6 = w_wr_en & (reg_addr == LPARA_DSIG_KEY_6_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_key_7 = w_wr_en & (reg_addr == LPARA_DSIG_KEY_7_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_key_8 = w_wr_en & (reg_addr == LPARA_DSIG_KEY_8_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_key_9 = w_wr_en & (reg_addr == LPARA_DSIG_KEY_9_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_key_10 = w_wr_en & (reg_addr == LPARA_DSIG_KEY_10_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_key_11 = w_wr_en & (reg_addr == LPARA_DSIG_KEY_11_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_dsig_key_12 = w_wr_en & (reg_addr == LPARA_DSIG_KEY_12_OFFSET[LPARA_ADDR_W-1:0]);
