  // Read data mux returns zero for addresses that do not map to a register.
  always_comb begin : p_com_rdata
    w_rdata_nxt = '0;
    case (32'(reg_addr))
      LPARA_DSIG_VERSION_OFFSET: w_rdata_nxt = w_dsig_version_value;
      LPARA_DSIG_CAP_ALG_OFFSET: w_rdata_nxt = w_dsig_cap_alg_value;
      LPARA_DSIG_CAP_KGEN_OFFSET: w_rdata_nxt = w_dsig_cap_kgen_value;
